"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3756],{3497(e){e.exports=JSON.parse('{"title":"\uba54\ubaa8\ub9ac RAM \uc0ac\uc6a9\ub960 \uc99d\uac00 \u2260 \uba54\ubaa8\ub9ac \ub204\uc218","date":"2025-04-29","coverUrl":"/kudzu-based-bench/assets/notion/7802627ebbe959da.png","html":"<h2 data-notion-block-id=\\"1e2e548d-8a8e-807b-a3bb-ee37e6f6e99e\\" id=\\"1e2e548d-8a8e-807b-a3bb-ee37e6f6e99e\\">\uba54\ubaa8\ub9ac RAM \uc0ac\uc6a9\ub960 \uc99d\uac00 \u2260 \uba54\ubaa8\ub9ac \ub204\uc218</h2><a href=\\"https://blog.platformatic.dev/optimizing-nodejs-performance-v8-memory-management-and-gc-tuning\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/optimizing-nodejs-performance-v8-memory-management-and-gc-tuning</a><p data-notion-block-id=\\"1dee548d-8a8e-806a-b373-dd72c4e0b755\\">Node.js\uc758 \uba54\ubaa8\ub9ac \uc0ac\uc6a9\ub960\uc774 \uce58\uc19f\ub294 \uac83\uc774 \ubb34\uc870\uac74 \uba54\ubaa8\ub9ac \ub204\uc218\uc778\uc9c0 \uc54c\uc544\ubcf4\uae30 \uc704\ud574 V8\uc758 GC\uac00 \uc5b4\ub5bb\uac8c \ubcf5\uc7a1\ud558\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uace0, \ucd94\uac00\ub85c Node.js 22\uc5d0\uc11c\uc758 \ubcc0\uacbd\uc774 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-80a7-ad45-d24a5e7e94d3\\" id=\\"1dbe548d-8a8e-80a7-ad45-d24a5e7e94d3\\">\uc624\ub958 \ucc98\ub9ac \uc544\uc774\ub514\uc5b4\ub4e4</h2><a href=\\"https://meowbark.dev/Better-error-handling\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://meowbark.dev/Better-error-handling</a><p data-notion-block-id=\\"1e2e548d-8a8e-80f9-bc13-f3ffcb733acd\\"><code>try...catch</code>\ubc29\uc2dd\uc758 \ub2e8\uc810\uc744 \uc54c\uc544\ubcf4\uace0, \ub2e4\ub978 \uc5b8\uc5b4\uc758 \uc544\uc774\ub514\uc5b4\ub97c \ucc28\uc6a9\ud574\uc11c \uad6c\ud604\uc744 \ud574\ubcf4\uace0, \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc774 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. <code>try...catch</code>\ubb38\uc81c\uc758 \ud574\uacb0\ucc45\uc744 \uc81c\uacf5\ud574\uc8fc\uc9c4 \uc54a\uc9c0\ub9cc, \ub2e4\ub978 \uc5b8\uc5b4\uc758 \uc544\uc774\ub514\uc5b4\ub97c \ubcf4\uace0, \uad00\uc810\uc744 \ub113\ud790 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e2e548d-8a8e-80e3-952e-fe932218ab1b\\" id=\\"1e2e548d-8a8e-80e3-952e-fe932218ab1b\\">CSS \ud6c4\ucc98\ub9ac\uae30\uac00 \uc8fc\ubaa9\ubc1b\ub294 \uc774\uc720</h2><a href=\\"https://css-tricks.com/so-you-want-to-give-up-css-pre-and-post-processors/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/so-you-want-to-give-up-css-pre-and-post-processors/</a><p data-notion-block-id=\\"1e2e548d-8a8e-8047-a88d-efefefc0a916\\">\uac04\ub2e8\ud558\uac8c CSS \uc804\ucc98\ub9ac\uae30\uc640 CSS \ud6c4\ucc98\ub9ac\uae30\uc758 \uac1c\ub150\uc744 \uc54c\uc544\ubcf4\uace0, CSS \ud6c4\ucc98\ub9ac\uae30\uac00 \ud604\uc7ac \uc8fc\ubaa9\ubc1b\ub294 \uc774\uc720\ub97c \uc124\uba85\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dee548d-8a8e-802e-8d48-c2ab6d4a1f6c\\" id=\\"1dee548d-8a8e-802e-8d48-c2ab6d4a1f6c\\">\uc694\uccad\uc740 \uc778\ud504\ub77c\ub97c \ud0c0\uace0</h2><a href=\\"https://vercel.com/blog/life-of-a-request-application-aware-routing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/life-of-a-request-application-aware-routing</a><p data-notion-block-id=\\"1dee548d-8a8e-8022-8bf4-eddcfce49986\\">Vercel \uc778\ud504\ub77c\uc5d0\uc11c\ub294 \uc0ac\uc6a9\uc790\uc758 \uc694\uccad\uc744 \uc5b4\ub5bb\uac8c \uc778\uc2dd\ud574\uc11c \uc815\ud655\ud55c \ubc30\ud3ec \ubc84\uc804\uc744 \uac00\ub9ac\ud0a4\uac8c \ud558\uace0, \ubc30\ud3ec \ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uc81c\uacf5\ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e2e548d-8a8e-80fa-90df-f0b9609e7d05\\" id=\\"1e2e548d-8a8e-80fa-90df-f0b9609e7d05\\">\uc131\ub2a5 \uac1c\uc120\uc744 \uc704\ud574 \uc54c\uc544\uc57c \ud560 \uac83.</h2><a href=\\"https://www.speedcurve.com/blog/web-performance-plateau/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.speedcurve.com/blog/web-performance-plateau/</a><p data-notion-block-id=\\"1e2e548d-8a8e-803b-91d1-c11da6f52b59\\">\uc131\ub2a5\uc744 \uc544\ubb34\ub9ac \ube60\ub974\uac8c \ud574\ub3c4 \ube44\uc9c0\ub2c8\uc2a4 \uc9c0\ud45c\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc73c\uba74 \uc758\ubbf8\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc774\ub97c \uc124\uba85\ud558\ub294 \uc9c0\ud45c\uc778 performance plateau\ub97c \uc54c\uc544\ubcf4\uace0, \uc65c \uc774 \uc9c0\ud45c\uac00 \uc911\uc694\ud55c\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://largeapps.dev/case-studies/advanced/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://largeapps.dev/case-studies/advanced/</a><p data-notion-block-id=\\"1e2e548d-8a8e-8068-83dc-d4953c86f4bf\\">\uc774 \uae00\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc0ac\uc774\ud2b8\uc5d0\uc11c \uc131\ub2a5 \uac1c\uc120\uc744 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc740 \uc800\ub9c8\ub2e4\uc758 \uc694\uad6c\uc0ac\ud56d\uc744 \uac00\uc9c0\uace0 \uc788\uc73c\ubbc0\ub85c, \uc5b4\ub290 \ubd80\ubd84\uc758 \uc131\ub2a5\uc744 \uac1c\uc120\ud574\uc57c \ud558\ub294\uc9c0\uc640 \ud574\uacb0 \ubc29\ubc95 \ubaa8\ub450 \ub2e4\ub985\ub2c8\ub2e4. \uadf8\ub807\uae30\uc5d0 \uc774 \uae00\uc5d0\uc11c \uc81c\uc2dc\ud558\ub294 \uc131\ub2a5 \uac1c\uc120 \uc608\uc2dc\uc640, \uc811\uadfc\ud558\ub294 \ubc29\uc2dd\uc740 \uc131\ub2a5 \uac1c\uc120\uc2dc\uc5d0 \ub418\uc0c8\uae38\ub9cc \ud569\ub2c8\ub2e4.</p><a href=\\"https://vercel.com/blog/guide-to-fast-websites-with-next-js-tips-for-maximizing-server-speeds#else:-partial-prerender-\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/guide-to-fast-websites-with-next-js-tips-for-maximizing-server-speeds#else:-partial-prerender-</a><p data-notion-block-id=\\"1dbe548d-8a8e-8045-94d3-e4f0f8f309cd\\">Next.js\uc5d0\uc11c\uc758 \uc131\ub2a5 \uac1c\uc120 \uac00\uc774\ub4dc\ub97c \ub098\uc5f4\ud574\ub193\uc740 \uae00\uc774\uc9c0\ub9cc, \uc131\ub2a5 \uac1c\uc120 \ud0a4\uc6cc\ub4dc\ub294 Next.js \uc678\uc5d0\uc11c\ub3c4 \uc801\uc6a9\ub418\ubbc0\ub85c, \uc131\ub2a5 \uac1c\uc120\uc744 \uc704\ud574 \ud0a4\uc6cc\ub4dc\ub294 \uc54c\uc544\ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://web.dev/learn/performance\\">web.dev\uc758 \uc131\ub2a5 \ubc30\uc6cc\ubcf4\uae30 \uc139\uc158</a>\ub3c4 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dee548d-8a8e-802a-975c-ecfede4d4b9a\\" id=\\"1dee548d-8a8e-802a-975c-ecfede4d4b9a\\">\ubc31\uc5d4\ub4dc\uc640 \ud504\ub860\ud2b8\uc5d4\ub4dc \ucef4\ud3ec\ub10c\ud2b8\ub85c \ubd84\ub9ac\ud558\uae30</h2><a href=\\"https://overreacted.io/impossible-components/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/impossible-components/</a><p data-notion-block-id=\\"1dee548d-8a8e-8094-a88d-e313c654b9b3\\">\uc11c\ubc84 \ucef4\ud3ec\ub10c\ud2b8\uc640 \ud074\ub77c\uc774\uc5b8\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ubc31\uc5d4\ub4dc \uae30\ub2a5\uc744 \ud558\ub294 \ucef4\ud3ec\ub10c\ud2b8, \ud504\ub860\ud2b8\uc5d4\ub4dc \uae30\ub2a5\uc744 \ud558\ub294 \ucef4\ud3ec\ub10c\ud2b8\ub85c \ub9cc\ub4e4\uc5b4 \ucef4\ud3ec\ub10c\ud2b8\uc5d0 \ub370\uc774\ud130\ub97c \uc804\ub2ec\ud558\ub294 \ubc29\ubc95\uc774\ub098 \ud569\uc131(composition)\uc744 \uc27d\uac8c \ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uc608\uc81c\uc640 \ud568\uaed8 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e2e548d-8a8e-8006-8b8b-ccdffbb6dde2\\" id=\\"1e2e548d-8a8e-8006-8b8b-ccdffbb6dde2\\"> \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc560\ub2c8\uba54\uc774\uc158, \ubcf5\uc81c \uc5c6\uc774.</h2><a href=\\"https://craftofui.substack.com/p/time-travel-with-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://craftofui.substack.com/p/time-travel-with-javascript</a><p data-notion-block-id=\\"1e0e548d-8a8e-80c6-8eaf-d50920ea2d52\\">\uc0ac\ub78c\ub4e4\uc774 \ubb34\ud55c\uc73c\ub85c \uc5f0\uacb0\ub418\ub294 \uce90\ub7ec\uc178\uc774\ub098 \ube44\uc2b7\ud55c \ubb34\ud55c\uc73c\ub85c \uc5f0\uacb0\ub418\ub294 \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c DOM\uc744 \uc0dd\uc131\ud558\ub294 \ud2b8\ub9ad\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 CSS \uc18d\uc131\uacfc \uc57d\uac04\uc758 JS\ub97c \uc0ac\uc6a9\ud574\uc11c DOM\uc744 \ubb34\ud55c\ud788 \uc0dd\uc131\ud558\ub294 \ud2b8\ub9ad \uc5c6\uc774 \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dee548d-8a8e-80fa-a325-f2bccab3ecdf\\" id=\\"1dee548d-8a8e-80fa-a325-f2bccab3ecdf\\">2025\ub144, \uc815\uc801 \uc0ac\uc774\ud2b8 \uc0dd\uc131\uae30\ub294.</h2><a href=\\"https://crystallize.com/blog/react-static-site-generators\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://crystallize.com/blog/react-static-site-generators</a><p data-notion-block-id=\\"1e2e548d-8a8e-8079-9925-fa5a9fe59613\\">React \uae30\ubc18 \uc815\uc801 \uc0ac\uc774\ud2b8 \uc0dd\uc131\uae30 \ub77c\uc774\ube0c\ub7ec\ub9ac/\ud504\ub808\uc784\uc6cc\ud06c\ub4e4\uc744 \uc0b4\ud3b4\ubcf4\uace0, \uc7a5\ub2e8\uc810\uacfc \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud558\uba74 \uc88b\uc740\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1e2e548d-8a8e-8096-bfd5-c73e95f4bc91\\" id=\\"1e2e548d-8a8e-8096-bfd5-c73e95f4bc91\\">\uc0c8\ub85c\uc6b4 \uc18c\uc2dd\ub4e4</h2><a href=\\"https://react.dev/blog/2025/04/21/react-compiler-rc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2025/04/21/react-compiler-rc</a><p data-notion-block-id=\\"1e2e548d-8a8e-8085-9b4b-cea1abf45184\\">React Compiler\uac00 RC\ubc84\uc804\uc73c\ub85c \uc62c\ub77c\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc5ec\ub7ec \uc9c0\uc6d0\uacfc \ub85c\ub4dc\ub9f5\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://react.dev/blog/2025/04/23/react-labs-view-transitions-activity-and-more\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2025/04/23/react-labs-view-transitions-activity-and-more</a><p data-notion-block-id=\\"1e2e548d-8a8e-8061-a550-d2c957a0a0ba\\">\uacf5\uc2dd\uc801\uc73c\ub85c <code>&#x3C;ViewTransition></code>\uacfc Offscreen API\ub97c \uc9c0\uc6d0\ud558\ub294 <code>&#x3C;Activity></code>, \uadf8\ub9ac\uace0 \uc5ec\ub7ec \ud3b8\uc758 \uae30\ub2a5\uc744 experimental \uae30\ub2a5\uc73c\ub85c \ucd94\uac00\ud588\uace0, \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/LegendApp/legend-list\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/LegendApp/legend-list</a><p data-notion-block-id=\\"1e4e548d-8a8e-80d4-bd50-d67edf07bbd4\\">React Native\uc5d0\uc11c JS\ub9cc\uc73c\ub85c <a href=\\"https://github.com/Shopify/flash-list\\">FlashList</a>\ubcf4\ub2e4 \uc88b\uc740 \uc131\ub2a5\uc744 \ub0b8\ub2e4\uace0 \ud558\ub294 \ub9ac\uc2a4\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. \uc544\uc9c1 \uc2e0\uc0dd \ub77c\uc774\ube0c\ub7ec\ub9ac\ub77c \ubaa8\ub4e0 \uacbd\uc6b0\ub97c \uc9c0\uc6d0\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubd10\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1dce548d-8a8e-80fd-9f31-d72da1e3850b\\" id=\\"1dce548d-8a8e-80fd-9f31-d72da1e3850b\\">\ubc88\uc678: \uae30\uc220 \uc120\ud0dd\uc740 \uc2e0\uc911\ud788.</h2><a href=\\"https://blog.bradfieldcs.com/you-are-not-google-84912cf44afb\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.bradfieldcs.com/you-are-not-google-84912cf44afb</a><p data-notion-block-id=\\"1e4e548d-8a8e-80a1-98b5-cd397093b784\\">\ube45\ud14c\ud06c\uc5d0\uc11c \ud2b9\uc815 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \ub9cc\ub4e0 \ucd5c\uc2e0 \uc720\ud589 \uae30\uc220\uc744 \uc120\ud0dd\ud558\ub294 \ub300\uc2e0\uc5d0, \uae30\uc220\uc758 \uc7a5\ub2e8\uc810\uc744 \uae00\uc4f4\uc774\uac00 \ub9cc\ub4e0 \ubc29\ubc95\ub860\uc744 \ud1b5\ud574 \ube44\ud310\uc801\uc73c\ub85c \ubc14\ub77c\ubd10\uc11c \ucd5c\uc801\uc758 \ub3c4\uad6c\ub97c \uc120\ud0dd\ud558\uae30\ub97c \uad8c\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://sliplane.io/blog/serverless-is-a-scam\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sliplane.io/blog/serverless-is-a-scam</a><p data-notion-block-id=\\"1e4e548d-8a8e-8020-858f-decb9fe4ff79\\">\uae00\uc740 \uc5b4\uadf8\ub85c\uc131\uc774 \uc9d9\uae30\ub3c4 \ud558\uace0, \uc57d\uac04\uc758 \ud3b8\ud5a5\uc131\uc774 \ud3ec\ud568\ub418\uc5b4\uc788\uc9c0\ub9cc, Serverless function\uc774 \uc0ac\uc6a9\uc131\uc774 \uc77c\ubc18\uc801\uc73c\ub85c \ud64d\ubcf4\ub418\uc5b4\uc788\ub294 \uac83\ubcf4\ub2e4 \uc88b\uc740 \uc0ac\uc6a9 \uc0ac\ub840\uac00 \uc801\uace0, \uc774 \uae00\ub610\ud55c (\ubb3c\ub860 container\ub97c \uc0ac\uc6a9\ud558\ub77c\uace0 \ud558\uace0\uc788\uae30\ub294 \ud558\uc9c0\ub9cc) \uc815\ub9d0 Serverless function\uc774 \ud544\uc694\ud55c\uc9c0 \ub2e8\uc810\uc744 \ub098\uc5f4\ud558\uace0 \ube44\ud310\uc801\uc73c\ub85c \uc120\ud0dd\ud558\uae30\ub97c \ubc14\ub77c\uace0 \uc788\uc2b5\ub2c8\ub2e4. Vercel\uc774 Serverless \ubc29\uc2dd\uc744 \ud3ec\uae30\ud55c \uac83\ucc98\ub7fc\uc694(<a href=\\"https://ones-to-watch.ethansup.net/news/post/3822cc46-45e8-4059-994b-1ab96c427c4c\\">Edge \ub7f0\ud0c0\uc784\uc758 \uc2dc\ub300\uac00 \uc544\uc9c1 \uc624\uc9c0 \uc54a\uc558\ub2e4</a>).</p>"}')}}]);